    "aiAssetAnalysis.copilot.executableStrategyPrompt.indicatorTimeframe": "Chart context timeframe: {timeframe}. Use it only to interpret the request; indicator code must not hardcode a timeframe.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.indicatorTimeframeDefault": "No chart timeframe was supplied. Indicator code must remain timeframe-agnostic.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.strategyTimeframe": "Source timeframe: {timeframe}. Preserve it in context.subscribe(frequency=...).",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.strategyTimeframeDefault": "No timeframe was supplied. Choose a conservative source-owned default and encode it in context.subscribe(frequency=...).",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.referenceTemplate": "Reference strategy/template: {template}",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.executionRules": "Execution rules:",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleNoConfirmation": "- Do not ask for confirmation when the target, timeframe, and strategy idea can be inferred.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleConservativeDefaults": "- Encode conservative missing knobs as code parameters or metadata, not prose outside the generated code.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleEnglishComments": "- Code comments must be English.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleNativeWorkflow": "- Stay inside QuantDinger native workflows.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleIndicatorCode": "- Generate runnable QuantDinger chart-indicator Python code for visualization only, not Strategy API V2 execution code.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleIndicatorSignals": "- Indicator output.signals are visual markers only. Do not emit ctx orders or open/close/add/reduce execution fields.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleChartAnnotations": "- Do not add output.layers by default. Use layers only when the user explicitly asks for zones, channels, support/resistance, invalidation areas, or when one sparse annotation materially improves readability.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleSparseAnnotations": "- Keep chart annotations professional and sparse: use short labels, dashed borders, translucent fills, and avoid opaque gray boxes that cover candles.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleScriptDraft": "- Generate only Python Strategy API V2 code that can be validated by QuantDinger. Declare the universe and subscriptions in initialize(context), use target-based order functions, and attach explicit protection rules to entries.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleScriptOwnership": "- The strategy source owns its canonical instrument, market type, subscription frequency, direction, sizing, entries, exits, risk rules, and schedules. The run panel owns only initial capital, date range, and permitted Crypto @swap leverage.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleScriptApis": "- Use only Strategy API V2 runtime APIs. Read current prices with data.current(...), positions through amount/avg_cost, and global order/schedule helpers; never use get_current_data, quantity/cost_basis, or context.run_daily.",
    "aiAssetAnalysis.copilot.executableStrategyPrompt.ruleTemplatePlan": "- For Template Strategy, return a concrete template strategy plan with parameters; do not auto-start live trading.",
